<?php
require_once __DIR__ . '/../controllers/helpers.php'; require_once __DIR__ . '/../config/database.php'; $user=requireRole(['etudiant']); $db=database();$idEvaluation=(int)($_GET['idEvaluation']??$_POST['idEvaluation']??0);$message=null;$erreur=null;
$check=$db->prepare('SELECT ev.idEvaluation,ev.titre FROM evaluation ev INNER JOIN module m ON m.idModule=ev.idModule INNER JOIN semestre sm ON sm.idSemestre=m.idSemestre INNER JOIN niveau n ON n.idNiveau=sm.idNiveau INNER JOIN inscription i ON i.idNiveau=n.idNiveau INNER JOIN dossier_etudiant d ON d.idDossier=i.idDossier WHERE ev.idEvaluation=:evaluation AND d.idEtudiant=:etudiant AND i.statut="VALIDEE"');$check->execute(['evaluation'=>$idEvaluation,'etudiant'=>$user['id']]);$evaluation=$check->fetch();
if($_SERVER['REQUEST_METHOD']==='POST' && $evaluation){$fichier=trim($_POST['fichier']??'');if(isset($_FILES['fichier_upload'])&&$_FILES['fichier_upload']['error']===UPLOAD_ERR_OK){$dir=__DIR__.'/../uploads/devoirs';if(!is_dir($dir)){mkdir($dir,0755,true);}$name=bin2hex(random_bytes(8)).'-'.basename($_FILES['fichier_upload']['name']);move_uploaded_file($_FILES['fichier_upload']['tmp_name'],$dir.'/'.$name);$fichier='/uploads/devoirs/'.$name;}if($fichier===''){$erreur='Indiquez un fichier ou une adresse de fichier.';}else{$delete=$db->prepare('DELETE FROM depot WHERE idEvaluation=:evaluation AND idEtudiant=:etudiant');$delete->execute(['evaluation'=>$idEvaluation,'etudiant'=>$user['id']]);$stmt=$db->prepare('INSERT INTO depot (fichier,idEvaluation,idEtudiant) VALUES (:fichier,:evaluation,:etudiant)');$stmt->execute(['fichier'=>$fichier,'evaluation'=>$idEvaluation,'etudiant'=>$user['id']]);$message='Travail déposé avec succès.';}}
$pageTitle='Déposer un travail';$showSidebar=true;require __DIR__.'/../includes/header.php';?><h2 style="margin-top:0;">Déposer un travail</h2><?php if($message):?><p style="color:#217a4b;"><?=htmlspecialchars($message)?></p><?php endif;?><?php if($erreur):?><p style="color:#c62828;"><?=htmlspecialchars($erreur)?></p><?php endif;?><?php if($evaluation):?><div class="card" style="max-width:640px;"><p><strong>Évaluation :</strong> <?=htmlspecialchars($evaluation['titre'])?></p><form method="post" enctype="multipart/form-data"><input type="hidden" name="idEvaluation" value="<?=$idEvaluation?>"><div class="form-field"><label for="fichier_upload">Fichier</label><input type="file" id="fichier_upload" name="fichier_upload"></div><div class="form-field"><label for="fichier">Ou adresse du fichier</label><input type="text" id="fichier" name="fichier" placeholder="/uploads/devoir.pdf"></div><button class="btn" type="submit">Déposer</button></form></div><?php else:?><p>Évaluation introuvable ou non accessible.</p><?php endif;?><?php require __DIR__.'/../includes/footer.php';?>